import { useState } from 'react';
import {
  JxStepper,
  JxButton,
  JxInputField,
  JxTextareaField,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  address: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyData: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  address: '',
};

export default function RegistrationWizard({
  onSubmit,
}: {
  onSubmit: (data: RegistrationData) => void;
}) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);

  const update = (field: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const canGoNext = () => {
    if (step === 0) {
      return data.fullName.trim() !== '' && data.email.trim() !== '';
    }
    if (step === 1) {
      return data.country.trim() !== '' && data.city.trim() !== '' && data.address.trim() !== '';
    }
    return true;
  };

  const goNext = () => setStep((s) => Math.min(s + 1, steps.length - 1));
  const goBack = () => setStep((s) => Math.max(s - 1, 0));

  const handleSubmit = () => {
    onSubmit(data);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxInputField
            label="Полное имя"
            required
            value={data.fullName}
            onChange={update('fullName')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={update('email')}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={update('phone')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxInputField
            label="Страна"
            required
            value={data.country}
            onChange={update('country')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={update('city')}
          />
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={data.address}
            onChange={(event) => setData((prev) => ({ ...prev, address: event.target.value }))}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxAlert intent="info" title="Проверьте данные перед отправкой">
            Убедитесь, что контактные данные и адрес указаны верно.
          </JxAlert>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-xs)' }}>
            <span>
              <strong>Имя:</strong> {data.fullName || '—'}
            </span>
            <span>
              <strong>Почта:</strong> {data.email || '—'}
            </span>
            <span>
              <strong>Телефон:</strong> {data.phone || '—'}
            </span>
            <span>
              <strong>Страна:</strong> {data.country || '—'}
            </span>
            <span>
              <strong>Город:</strong> {data.city || '—'}
            </span>
            <span>
              <strong>Адрес:</strong> {data.address || '—'}
            </span>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r-sm)' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext()} onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

